  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
}

class Salesperson extends Employee {}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : float
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

Boeing "1" -- "0..*" Contract : manages
Boeing "1" -- "0..*" Acquisition : builds
Airline "1" -- "0..*" Contract : signs
Contract "1" *-- "1..*" Acquisition : consists of
Contract "0..*" -- "1" Salesperson : managed by
Airline "0..1" -- "0..*" Airline : is mother of

